// ---------------------------------------------------------------------------
// Runtime codecs
// ---------------------------------------------------------------------------

export const NotebookCodecs = {
  notebook   : recordCodecs.json<NotebookData>({ validator: moduleValidators.validateNotebookData }),
  page       : recordCodecs.json<PageData>({ validator: moduleValidators.validatePageData }),
  delta      : recordCodecs.bytes(),
  attachment : recordCodecs.fileEnvelope({ formatId: 'notesd', maxContentBytes: 50000000 }),
  admin      : recordCodecs.json<AdminData>({ validator: moduleValidators.validateAdminData }),
  editor     : recordCodecs.json<EditorData>({ validator: moduleValidators.validateEditorData }),
  viewer     : recordCodecs.json<ViewerData>({ validator: moduleValidators.validateViewerData }),
} as const;

// ---------------------------------------------------------------------------
// Typed module
// ---------------------------------------------------------------------------

export const NotebookModule = defineModule({
  definition : NotebookDefinition,
  codecs     : NotebookCodecs,
});

